def is_palindrome_stack(text):
    s = ArrayStack(100)
    clean = ''
    for ch in text.lower():
        if 'a' <= ch <= 'z' or '0' <= ch <= '9':
            clean += ch
            s.push(ch)
    for ch in clean:
        if ch != s.pop():   # LIFO 특성상 맨 뒤 글자부터 꺼내어 앞 글자와 비교
            return False
    return True

