def is_palindrome_deque(text):
    dq = CircularDeque(100)
    for ch in text.lower():
        if 'a' <= ch <= 'z' or '0' <= ch <= '9':
            dq.addRear(ch)

    while dq.size() > 1:   # 원소가 2개 이상 남아 있을 때만 양끝 쌍 비교
        if dq.deleteFront() != dq.deleteRear():
            return False
    return True
